        "פחת שהושמט: בודקים אפשרות לתיקון דוח ותקופות; אין לקבוע שתמיד אבד לעולם. השפעת פחת שניתן היה לנכות במכירה נבחנת לפי החוק והמקרה.",
        "פחת מואץ דורש הוראה תקפה למועד הרכישה, ההפעלה והענף. הוראת הקורונה 2020–2021 אינה היתר כללי לרכישות 2025–2026."
