        "164 והצווים/תקנות קובעים קבוצות משלמים ותשלומים; לא כל מי שחייב לנהל ספרים מנכה אוטומטית מכל ספק. בודקים שכר, שירותים ונכסים, שכירות ותשלומים מיוחדים בנפרד. בלוח 2026, עמ׳ 16, מופיע גם מבחן מחזור 2024 של 5,300,000 ₪ לשירותים ונכסים עם חריגים; הוא אינו המבחן היחיד לכל משלם.",
        "בודקים אישור ניכוי תקף לסוג התשלום במועד התשלום, ולא אישור ניהול ספרים בלבד. אישור פטור הוא אישור לשיעור ניכוי, ואינו הוכחה שההוצאה מותרת או שהחשבונית אמיתית.",
        "32א(א) בנוסחו הנוכחי דורש שהמס נוכה והועבר לפקיד השומה וכן הוגש הדוח החייב לפי 166/171 עם שם, מען ומספר מזהה מדויקים של המקבל. סעיף 32א(ב) מחריג כשמוכח לפקיד השומה שהמקבל דיווח ושילם מס, נוכה והועבר לפי אישור, או שאין חובת ניכוי.",
        "יש להפריד שנים: חוזר 03/2026 מ־9.2.2026, סעיף 1.1.3, קובע תחולה לתשלומים והוצאות ששולמו מ־1.1.2026. את 2025 בודקים לפי הנוסח שחל אז. החוזר מוסיף שבמקרה הוצאה שעיקרה פרטית, כגון בית מגורים עם חלק עסקי, אי־ניכוי בחלק העסקי לא ישלול מכוח 32א את ההוצאה כולה; הדומיננטיות נבחנת לפי יחס השטחים. אין בכך היתר לניכוי הוצאה פרטית או ויתור על בדיקת שומה.",
        "126 הוא דיווח שנתי על שכר; 856 על תשלומים שאינם שכר לפי חובתם. דוחות שוטפים ואישורים למקבלים הם שכבות נפרדות. לא כותבים מועד 30 באפריל כאילו אין הארכות; עובדים עם הנחיית שנת הדוח ושומרים גם אישור קליטה/אישור הגשה תקין.",
        "170 עוסק בהכנסה חייבת לתושב חוץ, לא בכל העברה לחו״ל. בודקים מקור הכנסה, אמנה, סוג המקבל ואישור/הצהרה החלים; 25% ליחיד אינו שיעור אוניברסלי לחברה זרה.18(ה) קובע גם תנאי עיתוי לניכוי הוצאה רלוונטית."
